interface Folder {
  id: string;
  name: string;
  children: (Folder | File)[];
}

interface File {
  id: string;
  filename: string;
}

const initialData: Folder = {
  id: "root",
  name: "Root",
  children: [],
};

export function TreeFolder() {
  const renderTree = (folder: Folder) => {
    return (
      <div key={folder.id}>
        <div>
          <strong
            onClick={() => expandFolder(folder.id)}
            style={{ cursor: "pointer" }}
          >
            {"[+]"} {folder.name}
          </strong>
        </div>
      </div>
    );
  };

  return (
    <div>
      <p> Tree structure</p>
      {renderTree(initialData)}
    </div>
  );
}

export default TreeFolder;
